// SPDX-License-Identifier: MIT
// Facetlock Lattice (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/facetlock.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "facetlock:<seed>:<difficulty>"); the RNG is used only to scramble at setup.
// Byte parity goes through engines/unreal/core-test/facetlock_parity.txt (facetlock_core_test.cpp), generated by
// tools/minigames/facetlock_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

namespace daedalus { namespace facetlock {

inline const char* GameId() { return "facetlock"; }
inline const char* Title() { return "Facetlock Lattice"; }
inline const char* Marks() { return "ETVGU"; }

struct Difficulty { const char* Name; int Size; int Scramble; int Spare; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 3, 3, 4 }, { "normal", 4, 5, 4 }, { "hard", 5, 7, 3 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

constexpr int BoonDelta = 1;  // Spirit Boon (Thornkin): spare +1 per level (hephaestus R2-9; level 2 = 5+ summons)
/** FindDifficulty with a Spirit Boon level 0..2 applied to Spare (PrismGame boon, floor 0). Nullptr on a bad level. */
inline const Difficulty* FindDifficulty(const std::string& Name, int Boon)
{
	if (Boon == 0) return FindDifficulty(Name);
	if (Boon < 0 || Boon > 2) return nullptr;
	struct Boosted { Difficulty Table[2][DifficultyCount]; };
	static const Boosted B = [] {
		Boosted Out{};
		for (int L = 0; L < 2; ++L)
			for (int I = 0; I < DifficultyCount; ++I)
			{
				Out.Table[L][I] = Difficulties()[I];
				Out.Table[L][I].Spare = std::max(0, Out.Table[L][I].Spare + BoonDelta * (L + 1));
			}
		return Out;
	}();
	for (int I = 0; I < DifficultyCount; ++I)
	{
		if (Name == B.Table[Boon - 1][I].Name) return &B.Table[Boon - 1][I];
	}
	return nullptr;
}

/** One move: Row (true) or column, index, direction +1/-1. */
struct Move { bool Row; int Index; int Dir; bool operator==(const Move& O) const { return Row == O.Row && Index == O.Index && Dir == O.Dir; } };

/** facetlock.shift: slide row/column Index by Dir, wrapping. */
inline std::vector<std::string> Shift(const std::vector<std::string>& Board, const Move& M)
{
	const int N = static_cast<int>(Board.size());
	std::vector<std::string> B = Board;
	auto Wrap = [N](int X) { return ((X % N) + N) % N; };
	if (M.Row) { for (int J = 0; J < N; ++J) B[static_cast<size_t>(M.Index)][static_cast<size_t>(J)] = Board[static_cast<size_t>(M.Index)][static_cast<size_t>(Wrap(J - M.Dir))]; }
	else { for (int R = 0; R < N; ++R) B[static_cast<size_t>(R)][static_cast<size_t>(M.Index)] = Board[static_cast<size_t>(Wrap(R - M.Dir))][static_cast<size_t>(M.Index)]; }
	return B;
}

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<std::string> Board;
	std::vector<Move> Solution;   // front is the next move that undoes the scramble
	int Moves = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	int Size() const { return static_cast<int>(Board.size()); }
	std::vector<std::string> Target() const { std::vector<std::string> T; for (int R = 0; R < Diff->Size; ++R) T.push_back(std::string(static_cast<size_t>(Diff->Size), Marks()[R])); return T; }
	bool Solved() const { return Board == Target(); }

	bool Start(std::uint32_t Seed, const std::string& DifficultyName, int Boon = 0)
	{
		Diff = FindDifficulty(DifficultyName, Boon);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		const int N = Diff->Size;
		while (true)
		{
			std::vector<std::string> B = Target(); std::vector<Move> Sol; bool HasLast = false; Move Last{ true, 0, 0 };
			for (int S = 0; S < Diff->Scramble; ++S)
			{
				Move M{ true, 0, 0 };
				while (true)
				{
					M.Row = Rng.ChoiceIndex(2) == 0;
					M.Index = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(N)));
					M.Dir = Rng.ChoiceIndex(2) == 0 ? 1 : -1;
					if (!HasLast || !(M.Row == Last.Row && M.Index == Last.Index && M.Dir == -Last.Dir)) break;
				}
				B = Shift(B, M);
				Sol.insert(Sol.begin(), Move{ M.Row, M.Index, -M.Dir });
				Last = M; HasLast = true;
			}
			if (B != Target()) { Board = B; Solution = Sol; break; }
		}
		Moves = Diff->Scramble + Diff->Spare;
		return true;
	}

	enum class Act : int { Ok = 0, GameOver, BadMove };

	Act Apply(const Move& M, int& Gained)
	{
		Gained = 0;
		if (Over) return Act::GameOver;
		if (M.Index < 0 || M.Index >= Size() || (M.Dir != 1 && M.Dir != -1)) return Act::BadMove;
		Board = Shift(Board, M);
		--Moves;
		if (!Solution.empty() && Solution.front() == M) Solution.erase(Solution.begin());
		else Solution.insert(Solution.begin(), Move{ M.Row, M.Index, -M.Dir });
		if (Solved()) { Gained = 100 + 10 * Moves; Score += Gained; Over = true; Won = true; return Act::Ok; }
		if (Moves <= 0) { Over = true; Won = false; }
		return Act::Ok;
	}

	Move DemoAction() const { return Solution.empty() ? Move{ true, 0, 1 } : Solution.front(); }

	std::string BoardString() const { std::string S; for (size_t I = 0; I < Board.size(); ++I) { if (I) S.push_back('|'); S += Board[I]; } return S; }
	std::string SolutionString() const { std::string S; for (size_t I = 0; I < Solution.size(); ++I) { if (I) S.push_back(';'); S += Solution[I].Row ? 'r' : 'c'; S += ','; S += std::to_string(Solution[I].Index); S += ','; S += std::to_string(Solution[I].Dir); } return S; }
};

} } // namespace daedalus::facetlock
